"""Render the current modern-use model outputs into the Lagos HTML."""
from pathlib import Path
import base64
import html
import json


def render_model_sections(model_dir):
    root = Path(model_dir)
    p = json.loads((root / 'model_results.json').read_text())
    a = p['audit']
    assert a['demand_resolution'] == 'individual' and a['supply_resolution'] == 'urban_rural'
    labels = p['labels']
    n = a['common_n']
    co = {(r['model'], r['term']): r for r in p['coefficients']}
    tests = {(r['model'], r['block']): r for r in p['tests']}
    gaps = {r['term']: r for r in p['gaps']}
    D = ['agency', 'stigma', 'health', 'fertility', 'confidence', 'opposes']
    assert n == 1865 and a['need_n'] == 2159
    assert len(p['samples']) == 5 and all(r['n'] == n and r['lgas'] == 17 for r in p['samples'])
    esc = lambda v: html.escape(str(v), quote=True)
    fp = lambda v: '<0.001' if v < .001 else f'{v:.3f}'
    or_text = lambda r: f'{r["odds_ratio"]:.2f} ({r["or_lo"]:.2f}–{r["or_hi"]:.2f})'

    def download(file, label):
        data = base64.b64encode((root / file).read_bytes()).decode()
        return f'<a class="download" download="{file}" href="data:text/csv;base64,{data}">{esc(label)} ↓</a>'

    def figure(file, alt):
        data = base64.b64encode((root / file).read_bytes()).decode()
        return f'<figure class="model-figure"><img src="data:image/svg+xml;base64,{data}" alt="{esc(alt)}"></figure>'

    def coefficient_table(ids, titles, fields):
        rows = []
        for k in fields:
            cells = ''.join('<td>' + (or_text(co[m, k]) if (m, k) in co else 'Not included') + '</td>' for m in ids)
            rows.append(f'<tr><th scope="row">{esc(labels[k])}</th>{cells}</tr>')
        return '<div class="table-wrap"><table class="planning model-table"><thead><tr><th>Adjusted odds ratio (95% CI)</th>' + ''.join(f'<th>{esc(t)}</th>' for t in titles) + '</tr></thead><tbody>' + ''.join(rows) + '</tbody></table></div>'

    sjd, sjs = co['score_joint', 'demand_score'], co['score_joint', 'supply_risk']
    index_models = coefficient_table(['score_demand', 'supply', 'score_joint'],
                                    ['Demand risk score', 'Supply risk', 'Both scores'],
                                    ['demand_score', 'supply_risk'])
    score_tests = ''.join(f'<tr><th scope="row">{side}</th><td>{fp(tests["score_joint", side]["p"])}</td><td>{fp(tests["score_joint", side]["holm_p"])}</td></tr>' for side in ['Demand', 'Supply'])
    score_section = f'''<section id="models"><div class="section-heading"><div><span class="eyebrow">04 · ADJUSTED ASSOCIATIONS</span><h2>Modern contraceptive use, individual demand and local supply risk</h2></div><p>Woman-level logistic regression · FPN2 = 1</p></div>
<p class="model-meta"><strong>Outcome:</strong> current modern contraceptive use. Confirmed nonusers and traditional-only users are coded 0; confirmed modern users are coded 1. Unresolved use or method classifications are excluded from models.</p>
<p class="model-meta"><strong>All models adjust for:</strong> age and age squared, education, partnership status, fertility goal and urban/rural residence. Original SURGO woman weights · 17 LGAs · no random effects or interactions.</p>
<div class="rule-strip"><span><b>Demand risk score:</b> each woman's average standardized concern score.</span><span><b>Supply risk score:</b> −1 × the matched LGA–rural/urban supply-readiness score.</span><span>Higher values on both axes mean less favorable conditions.</span></div>
<p class="model-note"><strong>Demand risk score · personal responses.</strong> These main models use an equal-weight average of z-scores, not PCA. The six inputs are healthcare permission barriers, anticipated social stigma, health/side-effect beliefs, future-fertility concerns, low method confidence (displayed as “Low method knowledge”) and opposition to FP. Each is coded 1 = concern, 0 = no concern. For each item, subtract its SURGO-weighted mean among valid FPN2 = 1 respondents and divide by its weighted population SD. Average the woman's six standardized responses; all six are required. The same formula applies wherever she lives. This gives {a["demand_distinct_values_model"]} distinct personal scores among {n:,} modeled women. Identical response patterns receive identical scores. The LGA planning demand index is separate and is not used in these models.</p>
<p class="model-note"><strong>Supply risk score · assigned service environment.</strong> Start with the six facility summaries assigned by her exact LGA and rural/urban status: short + long-acting offering, free-product provision, trained-provider share, counselor availability, three-LARC stock breadth and most-popular-product stock. Rural women receive rural summaries and urban women urban summaries within the same LGA. Standardize each profile measure using that component's fixed mean and sample SD across the 17 LGA-wide planning summaries; average the six standardized values and multiply by −1. Because all six raw supply measures run higher = stronger provision, this reversal makes higher supply risk = weaker recorded provision. Women in the same profile share a supply risk score. There are {a["supply_profiles"]} observed profiles; inference remains clustered across 17 LGAs.</p>
<p class="model-note">Both scores enter continuously in their original average-z units, with no median split or final-index restandardization. They are not percentages or 0–100 scales, and zero does not mean no barriers. PCA-weighted alternatives are presented separately in the appendix.</p>
<p class="model-note"><strong>Approved component fallback:</strong> Ibeju-Lekki–Urban has no known most-popular-product stock status. Only that component uses the LGA value; its other five components remain Urban-specific. This is flagged for {a["fallback_need"]} women in need, of whom {a["fallback_model_n"]} are complete cases in these models. The original missing stock-status value is preserved.</p>
<div class="table-wrap"><table class="planning model-table"><thead><tr><th>Model</th><th>Predictors, in addition to the same covariates</th></tr></thead><tbody><tr><th>1 · Demand risk score</th><td>logit P(modern use) = intercept + demand score + covariates</td></tr><tr><th>2 · Supply risk</th><td>logit P(modern use) = intercept + supply risk score + covariates</td></tr><tr><th>3 · Both scores</th><td>logit P(modern use) = intercept + demand score + supply risk score + covariates</td></tr></tbody></table></div>
<p class="model-note"><strong>Comparable model sample:</strong> {n:,} of 2,159 women in need, including {a['common_events']:,} confirmed modern users. All five distinct models in Sections 4–5 use the same complete-case women. The overview and geographic summaries retain their original FPN2 = 1 denominators.</p>
{figure('01_score_models.svg', 'Three modern-use weighted logistic models: demand risk score only, supply risk score only, and both scores, each with the same covariates and capped 95% LGA-clustered intervals.')}
<p class="model-key"><strong>Key finding.</strong> In the both-score model, the demand-score odds ratio is <b>{or_text(sjd)}</b> and the supply-risk odds ratio is <b>{or_text(sjs)}</b> per one original index point. The individual demand-score interval is below 1; the supply-risk interval includes 1. Higher reported concerns are associated with lower modern-use odds after covariate and supply-risk adjustment, while the selected supply index has no clear adjusted association.</p>
{index_models}
{figure('02_score_probabilities.svg', 'Adjusted modern-use probability curves across observed individual demand and supply risk scores: single-score models dashed and both-score model solid, with pointwise 95% intervals for the joint model.')}
<p class="model-key"><strong>Planning interpretation.</strong> Modern-use probability decreases as the individual concern score increases. The supply-risk curve remains uncertain after accounting for demand. This supports investigating women's concerns alongside recorded service weaknesses; it does not establish that supply is unimportant or estimate the impact of an intervention.</p>
<details class="model-detail"><summary>Score construction, model tests and interpretation</summary><p>The two tests in the both-score model each test whether that score's coefficient is zero, conditional on the other score and covariates. Holm correction is applied across these two tests only. They do not test whether demand matters more than supply or attribute a percentage of nonuse.</p><div class="table-wrap"><table class="planning model-table"><thead><tr><th>Block in both-score model</th><th>Raw p</th><th>Holm p</th></tr></thead><tbody>{score_tests}</tbody></table></div><p>An odds ratio is a change in odds, not a percentage-point change in use. The curves translate the fitted coefficients into weighted average probabilities. Each score is varied over its observed range while other predictors retain their observed values; profiles need not be jointly observed and are not intervention forecasts.</p><p>The individual score uses six binary inputs, so at most 64 response patterns are possible; it need not have a unique value for every woman or the same number of values as supply risk. Standardization uses the weighted mean and weighted population standard deviation within the supplied need group, with item-specific valid denominators. Missing responses are not coded zero. These six equally weighted standardized concerns form a planning-oriented composite, not a validated psychological scale. Equal standardized weights do not imply equal raw-percentage or intervention effects.</p>{download('individual_demand_score_reference.csv', 'Individual score means, SDs and denominators')}</details>
<div class="table-heading">{download('model_coefficients.csv', 'All coefficients and intervals')}{download('model_block_tests.csv', 'Block tests')}</div></section>'''

    components = coefficient_table(['components_demand', 'supply', 'components_joint'],
                                   ['Six individual concerns', 'Supply risk', 'Six concerns + supply risk'],
                                   D + ['supply_risk'])
    conf, oppose = gaps['confidence'], gaps['opposes']
    probability_rows = ''.join(f'<tr><th scope="row">{esc(labels[k])}</th><td>{100*gaps[k]["probability_absent"]:.1f}%</td><td>{100*gaps[k]["probability_present"]:.1f}%</td><td>{100*gaps[k]["estimate"]:+.1f} ({100*gaps[k]["lo"]:+.1f} to {100*gaps[k]["hi"]:+.1f})</td></tr>' for k in D)
    component_tests = ''.join(f'<tr><th scope="row">{side}</th><td>{int(tests["components_joint", side]["df_num"])}</td><td>{fp(tests["components_joint", side]["p"])}</td><td>{fp(tests["components_joint", side]["holm_p"])}</td></tr>' for side in ['Demand', 'Supply'])
    max_vif = max(r['max_vif'] for r in p['samples'])
    sample_rows = ''.join(f'<tr><th scope="row">{esc(title)}</th><td>{r["n"]:,}</td><td>{r["events"]:,}</td><td>{r["parameters"]}</td><td>{r["max_vif"]:.2f}</td></tr>' for r, title in zip(p['samples'], ['Demand risk score', 'Supply risk', 'Both scores', 'Six individual concerns', 'Six concerns + supply risk']))
    component_section = f'''<section id="individual-models"><div class="section-heading"><div><span class="eyebrow">05 · ADJUSTED ASSOCIATIONS</span><h2>Individual demand concerns alongside local supply risk</h2></div><p>Six concerns entered separately · same {n:,} women</p></div>
<p class="model-meta"><strong>Same outcome, weights and covariates:</strong> confirmed modern use, original SURGO weights, age and age squared, education, partnership, fertility goal and urban/rural residence. No random effects or interactions.</p>
<p class="model-note">These models replace the demand risk score with the six individual binary demand indicators. Each indicator describes that woman's own responses. Supply risk remains the same matched LGA–rural/urban score used in Section 4. The supply-only model is identical to Model 2 above and is repeated to keep the comparison clear.</p>
<div class="table-wrap"><table class="planning model-table"><thead><tr><th>Model</th><th>Predictors, in addition to the same covariates</th></tr></thead><tbody><tr><th>4 · Individual concerns</th><td>Six separate woman-level indicators: healthcare permission, stigma, health/side-effect beliefs, fertility concerns, low method confidence and opposition to FP.</td></tr><tr><th>2 · Supply risk, repeated</th><td>The continuous supply risk score.</td></tr><tr><th>5 · Individual concerns + supply risk</th><td>All six woman-level indicators together with the continuous supply risk score.</td></tr></tbody></table></div>
{figure('03_component_models.svg', 'Modern-use coefficient plots for six individual demand indicators, local supply risk alone, and six individual indicators plus local supply risk. All models have the same covariates and women, with capped 95% CR2 intervals.')}
<p class="model-key"><strong>Key finding.</strong> Opposition to FP and low method confidence are associated with lower modern-use odds after adjustment. In Model 5, their odds ratios are <b>{or_text(co['components_joint', 'opposes'])}</b> and <b>{or_text(co['components_joint', 'confidence'])}</b>. The supply-risk estimate is <b>{or_text(co['components_joint', 'supply_risk'])}</b>. The six individual indicators jointly show an association (raw p = {fp(tests['components_joint', 'Demand']['p'])}; Holm p = {fp(tests['components_joint', 'Demand']['holm_p'])}).</p>
{figure('04_component_probability_gaps.svg', 'Adjusted percentage-point gaps in predicted modern use for each individual concern present versus absent, from the six-indicator plus supply-risk model, with capped 95% intervals.')}
<p class="model-key"><strong>What this tells the planning team.</strong> The adjusted modern-use difference is <b>{100*oppose['estimate']:.1f} percentage points</b> for reported opposition and <b>{100*conf['estimate']:.1f} points</b> for low method confidence. These associations identify areas for further program investigation, including acceptability and confidence choosing or managing a method. They do not quantify the increase that a campaign or counseling intervention would produce. Other individual concerns have intervals crossing zero in this specification.</p>
<details class="model-detail"><summary>Exact coefficients, predicted probabilities and joint tests</summary>{components}<p>Probability profiles below come from Model 5. Other predictors retain their observed values. Both profiles are calculated for the same women and averaged with SURGO weights. Gap intervals use the full coefficient covariance, including covariance between the paired predictions.</p><div class="table-wrap"><table class="planning model-table"><thead><tr><th>Reported concern</th><th>Predicted use: absent</th><th>Predicted use: present</th><th>Gap, pp (95% CI)</th></tr></thead><tbody>{probability_rows}</tbody></table></div><p>The demand block tests all six individual coefficients jointly against zero; the supply test is the single supply-risk coefficient. Holm adjustment is within these two tests.</p><div class="table-wrap"><table class="planning model-table"><thead><tr><th>Block in Model 5</th><th>Restrictions</th><th>Raw p</th><th>Holm p</th></tr></thead><tbody>{component_tests}</tbody></table></div></details>
<details class="model-detail" id="model-checks"><summary>Sample, model checks and limits to inference</summary><p><strong>Eligibility:</strong> original SURGO FPN2 = 1. Of 2,159 women, {a['unresolved_modern_in_need']} have unresolved modern-use status. {a['known_modern_and_covariates_n']:,} have known status and complete covariates; requiring valid responses to all six demand indicators gives the common {n:,}-woman model sample. This retains {100*a['eligible_weight_share']:.1f}% of the need-group survey weight. The reference fertility-goal category is next child in 1–3 years; after-marriage and uncertain/unstated responses are retained as separate categories.</p>
<div class="table-wrap"><table class="planning model-table"><thead><tr><th>Distinct specification</th><th>Women</th><th>Modern users</th><th>Parameters, including intercept</th><th>Largest VIF</th></tr></thead><tbody>{sample_rows}</tbody></table></div>
<p>All five models converged, had full-rank designs and finite coefficients. Maximum VIF was {max_vif:.2f}. Weighted logistic coefficients match the corresponding svyglm point estimates to numerical precision. Leaving out one LGA at a time preserves the negative coefficient signs for the demand index, opposition and low confidence. The near-zero joint supply-risk coefficient changes sign across deletions, reinforcing its uncertain interpretation.</p>
<p><strong>Uncertainty:</strong> 95% coefficient intervals use LGA-clustered CR2 covariance and coefficient-specific Satterthwaite degrees of freedom. The supply-risk terms have approximately 2.6 effective degrees of freedom, reflecting concentrated geographic leverage despite the woman-level sample size. The Ibeju-Lekki–Urban facility profile is based on one facility; its component fallback and profile counts are downloadable. LGA clustering uses a known geographic group, not a verified official survey PSU. Official EA/stratum fields are unconfirmed; full complex-survey design inference cannot be claimed. The Senegal source scripts used weights-only estimation. These models add geographic clustering, and contain no random effects.</p>
<p><strong>What has not been established:</strong> no formal power analysis has been conducted. There are still only 17 LGA contexts, even though the regressions have woman-level rows. Intervals condition on the estimated scores; their construction uncertainty has not been propagated. Cross-sectional associations cannot establish causal binding constraints, demand-versus-supply contribution percentages, or that a nonsignificant supply score means supply is adequate.</p>
<p>Methods: <a href="https://jepusto.github.io/clubSandwich/reference/vcovCR.glm.html">CR2 covariance for weighted GLMs</a>; <a href="https://jepusto.github.io/clubSandwich/reference/Wald_test.html">small-sample block tests</a>; <a href="https://r-survey.r-forge.r-project.org/pkgdown/docs/reference/svyglm.html">survey-weighted GLMs</a>.</p>
<div class="table-heading">{download('model_supply_profiles.csv', 'Matched supply profiles and fallback flags')}{download('model_samples.csv', 'Model sample and fit checks')}{download('model_missingness.csv', 'Missingness')}{download('model_vifs.csv', 'VIF checks')}{download('leave_one_lga_out.csv', 'LGA-deletion coefficients')}</div></details>
<p class="footnote">“Low method knowledge” retains the previous display label; MC5a/b measure self-reported confidence choosing/managing a method, not objective factual knowledge. All plotted intervals are pointwise 95%; coefficient plots omit adjustment terms for readability, but the download includes every coefficient.</p>
<div class="table-heading">{download('individual_demand_probability_gaps.csv', 'Predicted probabilities and gaps')}{download('score_predicted_probabilities.csv', 'Score probability curves')}</div></section>'''
    return score_section + component_section
